SELECT `id`, `order` FROM `orders` WHERE `status` = 'open';
SELECT `order details`.`unit price` FROM `order details`;
SELECT 'it\'s' AS s;
SELECT "double quoted string" FROM dual;
INSERT INTO t (a, b) VALUES (1, 'x') ON DUPLICATE KEY UPDATE b = VALUES(b);
SELECT * FROM t LIMIT 10, 20;
SELECT @rownum := @rownum + 1 AS rn FROM t;
CREATE TABLE t (id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, name VARCHAR(20)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
SELECT * FROM t WHERE a REGEXP '^x';
UPDATE t SET a = a + 1 ORDER BY id LIMIT 5;
SELECT DATE_FORMAT(created_at, '%Y-%m') AS ym, COUNT(*) FROM t GROUP BY ym WITH ROLLUP;
SELECT * FROM t1 STRAIGHT_JOIN t2 ON t1.id = t2.id;
REPLACE INTO t (id, a) VALUES (1, 2);
SHOW TABLES;
SELECT JSON_EXTRACT(doc, '$.a'), doc->>'$.b' FROM t;
SELECT 1 # hash comment\n;
SELECT * FROM t WHERE id = ?;
SELECT CAST(x AS UNSIGNED), CONVERT(y, CHAR) FROM t;
DESCRIBE t;
